for folder in ("src", "tests"):  # replaced completely so no old files linger
    if os.path.isdir(folder):
        shutil.rmtree(folder)

with tarfile.open(fileobj=io.BytesIO(base64.b64decode("".join(DATA.split()))), mode="r:gz") as tar:
    tar.extractall(".", filter="data")
print("Updated RDFX bot files.")


# Headlines should be plain text, not links. Only touches the old link-style line; any
# wording you changed yourself is left alone.
path = "messages/templates.yaml"
old = "headline_item: '<a href=\"{url}\">{title}</a> ({source})'"
if os.path.exists(path):
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    if old in text:
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(text.replace(old, "headline_item: '{title} ({source})'"))
        print("News headlines switched to plain text (no links).")

# Economic calendar: condensed to one line per event. Only converts the original layout;
# if you changed that wording yourself it is left alone.
old_block = "  event_block: |\n    •{flag} {title}\n    {impact} {time} UK time · Forecast: {forecast} · Previous: {previous}\n"
new_block = ('  event_block: "{impact} {time} {flag} {title} · F {forecast} · P {previous}"\n'
             '  event_join: "\\n"\n')
if os.path.exists(path):
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    if old_block in text:
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(text.replace(old_block, new_block))
        print("Economic calendar switched to the compact one-line layout.")

# Failure notices + tracked links settings: added to config/settings.yaml once, nothing else in it is touched.
SETTINGS = "config/settings.yaml"
BLOCK = """
# ---------------------------------------------------------------------------
# Failure notices: the bot messages YOU privately if a scheduled post fails
# or a plan-B message had to be used.
# 1) Open a chat with your bot, press Start and send /myid (reply can take ~5 minutes)
# 2) Put the number it sends back here:
admin_chat_id: ""
failure_notices: true

# ---------------------------------------------------------------------------
# Tracked links: every funnel and social button link carries the id of the message that posted it.
#   Tally form:  add a hidden field called "source" and it records the message id with each application.
#   VIP (t.me chat link): the chat opens with the text below pre-typed, ending with the tag.
#   Websites with analytics: utm_source / utm_medium / utm_campaign are added.
tracking:
  enabled: true
  utm_source: telegram
  tally_field: source
  chat_text: "Hi Ryan, I'd like to join RDFX VIP. Ref: {ref}"
"""
if os.path.exists(SETTINGS):
    with open(SETTINGS, encoding="utf-8") as fh:
        current = fh.read()
    if "tracking:" not in current and "admin_chat_id" not in current:
        with open(SETTINGS, "a", encoding="utf-8") as fh:
            fh.write(BLOCK)
        print("Added failure-notice and tracked-link settings to config/settings.yaml.")

# Clean up the short-lived signals file from the earlier test version, if it was installed.
if os.path.exists("messages/signals.yaml"):
    os.remove("messages/signals.yaml")

# Earlier version used the long message id in the pre-typed VIP text. Switch the untouched old line to the short ref code.
if os.path.exists(SETTINGS):
    with open(SETTINGS, encoding="utf-8") as fh:
        current = fh.read()
    old_line = 'chat_text: "Hi Ryan, I\'d like to join RDFX VIP. (ref: {tag})"'
    if old_line in current:
        with open(SETTINGS, "w", encoding="utf-8") as fh:
            fh.write(current.replace(old_line, 'chat_text: "Hi Ryan, I\'d like to join RDFX VIP. Ref: {ref}"'))
        print("VIP pre-typed message now uses a short ref code.")
